SubProceso OrdenarDos(a Como Entero Por Referencia, b Como Entero Por Referencia)
  Si a > b Entonces
    Definir guardado Como Entero <- a;
    a <- b;
    b <- guardado;
  FinSi
FinSubProceso

Algoritmo Principal
  Definir primero, segundo Como Entero;
  Leer primero;
  Leer segundo;
  OrdenarDos(primero, segundo);
  Escribir primero, " ", segundo;
FinAlgoritmo
